(41336, 'Exodus 25:36', 'Exodus', 25, 36, 'غوټۍ ګانې، څانګې او څراغدان دې د ټکول شویو سوچه سرو زرو د یوې ټوټې څخه وي.', 'غوتی ګانې، چانګې او چراغدان دې د تکول شویو سوچه سرو زرو د یوې توتې چخه وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_25_36.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41337, 'Exodus 25:37', 'Exodus', 25, 37, 'د څراغدان دپاره اووه څراغونه جوړ کړه او ویې دروه، ترڅو مخې ته رڼا ورکړي.', 'د چراغدان دپاره اووه چراغونه جور کره او ویې دروه، ترچو مخې ته رنا ورکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_25_37.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41338, 'Exodus 25:38', 'Exodus', 25, 38, 'د هغه پلته پاکوونکي او پتنوسونه دې د سوچه سرو زرو وي.', 'د هغه پلته پاکوونکی او پتنوسونه دې د سوچه سرو زرو وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_25_38.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41339, 'Exodus 25:39', 'Exodus', 25, 39, 'د څراغدان او د هغه د ټول سامان په جوړولو کې د څلوردېرشو کیلو ګرامه سوچه سرو زرو څخه کار واخله.', 'د چراغدان او د هغه د تول سامان په جورولو کې د چلوردېرشو کیلو ګرامه سوچه سرو زرو چخه کار واخله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_25_39.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41340, 'Exodus 25:40', 'Exodus', 25, 40, 'دې خبرې ته پام وکړه چې دا د هغې نمونې له مخې جوړ کړې چې ما درته د غره په سر باندې دروښودله.', 'دې خبرې ته پام وکره چې دا د هغې نمونې له مخې جور کرې چې ما درته د غره په سر باندې دروشودله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_25_40.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41341, 'Numbers 30:1', 'Numbers', 30, 1, 'موسی د اسراییلو د قبیلو مشرانو ته د څښتن دغه حکمونه ورکړل:', 'موسی د اسراییلو د قبیلو مشرانو ته د چشتن دغه حکمونه ورکرل:', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_30_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41342, 'Numbers 30:2', 'Numbers', 30, 2, '«کله چې یو سړی څښتن ته یو شی نذر ورکوي، یا داسې قسم وخوري چې د ځینو شیانو څخه به ځان لېرې ساتي، نو هغه باید خپله وعده ماته نه کړي، بلکې څه چې یې ویلي دي هغه دې سرته ورسوي.', '«کله چې یو سری چشتن ته یو شی نذر ورکوی، یا داسې قسم وخوری چې د جینو شیانو چخه به جان لېرې ساتی، نو هغه باید خپله وعده ماته نه کری، بلکې چه چې یې ویلی دی هغه دې سرته ورسوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_30_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41343, 'Numbers 30:3', 'Numbers', 30, 3, 'که چېرې یوه پېغله چې د خپل پلار په کور کې اوسیږي، څښتن ته کوم شی نذر ورکوي یا داسې وعده کوي چې د ځینو شیانو څخه به ځان لېرې ساتي،', 'که چېرې یوه پېغله چې د خپل پلار په کور کې اوسیزی، چشتن ته کوم شی نذر ورکوی یا داسې وعده کوی چې د جینو شیانو چخه به جان لېرې ساتی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_30_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41344, 'Numbers 30:4', 'Numbers', 30, 4, 'که چېرې د هغې پلار د هغې څخه خبر شي او څه ونه وایي، نو هغه باید خپل نذر ورکړي یا خپله وعده پوره کړي.', 'که چېرې د هغې پلار د هغې چخه خبر شی او چه ونه وایی، نو هغه باید خپل نذر ورکری یا خپله وعده پوره کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_30_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41345, 'Numbers 30:5', 'Numbers', 30, 5, 'خو که چېرې د هغې پلار د هغې څخه خبر شي او هغه د نذر ورکولو څخه منع کړي، هغه د خپلې وعدې په پوره کولو باندې مجبوره نه ده. څښتن به هغه وبخښي، ځکه چې پلار یې منع کړې ده.', 'خو که چېرې د هغې پلار د هغې چخه خبر شی او هغه د نذر ورکولو چخه منع کری، هغه د خپلې وعدې په پوره کولو باندې مجبوره نه ده. چشتن به هغه وبخشی، جکه چې پلار یې منع کرې ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_30_5.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(41346, 'Numbers 30:8', 'Numbers', 30, 8, 'خو که چېرې د هغې مېړه ورڅخه خبر شي او هغه د نذر د پوره کولو څخه منع کړي، نو هغه ښځه د خپلې وعدې په پوره کولو باندې مجبوره نه ده. څښتن به هغه وبخښي.', 'خو که چېرې د هغې مېره ورچخه خبر شی او هغه د نذر د پوره کولو چخه منع کری، نو هغه شجه د خپلې وعدې په پوره کولو باندې مجبوره نه ده. چشتن به هغه وبخشی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_30_8.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(41347, 'Numbers 30:9', 'Numbers', 30, 9, 'کونډې او طلاق شوې ښځې باید هر هغه نذر او یا خپله وعده سرته ورسوي چې څښتن سره یې کړې ده.', 'کوندې او طلاق شوې شجې باید هر هغه نذر او یا خپله وعده سرته ورسوی چې چشتن سره یې کرې ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_30_9.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(41348, 'Numbers 30:10', 'Numbers', 30, 10, 'فرض کړئ یوه واده شوې ښځه څښتن ته یو نذر ومني او یا کومه وعده وکړي.', 'فرض کری یوه واده شوې شجه چشتن ته یو نذر ومنی او یا کومه وعده وکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_30_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(41349, 'Numbers 30:11', 'Numbers', 30, 11, 'که چېرې د هغې مېړه ورڅخه خبر شي او څه ونه وایي، نو هغې ښځې چې کومه وعده کړې یا هر نذر چې هغې منلی وي باید هغه سرته ورسوي.', 'که چېرې د هغې مېره ورچخه خبر شی او چه ونه وایی، نو هغې شجې چې کومه وعده کرې یا هر نذر چې هغې منلی وی باید هغه سرته ورسوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_30_11.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(41350, 'Numbers 30:12', 'Numbers', 30, 12, 'خو که چېرې د هغې مېړه خبر شي او هغه د نذر د پوره کولو څخه منع کړي، نو هغه یې په سرته رسولو مجبوره نه ده. څښتن به هغه وبخښي، ځکه چې مېړه یې د نذر پوره کولو څخه منع کړې ده.', 'خو که چېرې د هغې مېره خبر شی او هغه د نذر د پوره کولو چخه منع کری، نو هغه یې په سرته رسولو مجبوره نه ده. چشتن به هغه وبخشی، جکه چې مېره یې د نذر پوره کولو چخه منع کرې ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_30_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(41351, 'Numbers 30:13', 'Numbers', 30, 13, 'د هغې مېړه دا حق لري چې کوم نذر هغې منلی دی او یا یې کومه وعده کړې ده، هغه تایید او یا رد کړي.', 'د هغې مېره دا حق لری چې کوم نذر هغې منلی دی او یا یې کومه وعده کرې ده، هغه تایید او یا رد کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_30_13.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(41352, 'Numbers 30:14', 'Numbers', 30, 14, 'که چېرې د هغې مېړه په هماغه ورځ د نذر څخه خبر شي او څه ونه وایي، نو د هر شي نذر چې هغې منلی وي او یا یې وعده کړې وي هغه باید سرته ورسوي.', 'که چېرې د هغې مېره په هماغه ورج د نذر چخه خبر شی او چه ونه وایی، نو د هر شی نذر چې هغې منلی وی او یا یې وعده کرې وی هغه باید سرته ورسوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_30_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41353, 'Numbers 30:15', 'Numbers', 30, 15, 'خو که چېرې د هغې مېړه دا نذر وروسته رد کړي، نو د هغې ګناه به د هغه په غاړه وي.»', 'خو که چېرې د هغې مېره دا نذر وروسته رد کری، نو د هغې ګناه به د هغه په غاره وی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_30_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41354, 'Numbers 30:16', 'Numbers', 30, 16, 'دا هغه قوانین دي چې څښتن موسی ته د هغو نذرونو په اړه ورکړل چې د پېغلو له خوا چې د پلار په کور کې اوسیږي، ورکول کیږي او د هغو ښځو له خوا چې واده شوې وي.', 'دا هغه قوانین دی چې چشتن موسی ته د هغو نذرونو په اره ورکرل چې د پېغلو له خوا چې د پلار په کور کې اوسیزی، ورکول کیزی او د هغو شجو له خوا چې واده شوې وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_30_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41355, 'Proverbs 18:1', 'Proverbs', 18, 1, 'ځان غوښتونکی انسان د خلکو نه ځان لېرې ساتي او تل د حکمت مخالفت کوي.', 'جان غوشتونکی انسان د خلکو نه جان لېرې ساتی او تل د حکمت مخالفت کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs018_verse_001.mp3', 'https://drive.google.com/file/d/1XCgrxf_7pDyGnf3zAKRQLiryWpAI1z1v/preview', 1761237841, 1761237841),
(41356, 'Proverbs 18:2', 'Proverbs', 18, 2, 'کم‌عقل سړی د پوهې سره مینه نه لري او یوازې د خپل نظر په څرګندولو خوشحالیږي.', 'کم‌عقل سری د پوهې سره مینه نه لری او یوازې د خپل نظر په چرګندولو خوشحالیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs018_verse_002.mp3', 'https://drive.google.com/file/d/1_fj6cT-1o_s9HpA6hx6yS3txAwKDyMEf/preview', 1761237841, 1761237841),
